SELECT (SELECT count(*) FROM pg_tables WHERE schemaname='public') AS total_tablas, (SELECT count(*) FROM pg_tables WHERE schemaname='public' AND tablename IN ('guia_alimentacion','rutinas_recomendadas','biometria_huellas','cuentas_portal_web','plan_beneficios','beneficios_maestros','logs_personalizacion','inventario_productos','metodos_pago','config_portal_publico','config_global','promociones')) AS sin_uso_que_siguen;